<?php
require __DIR__.'/config.php';
require_admin();
$id=(int)($_GET['id']??0);
$st=$pdo->prepare('SELECT * FROM orders WHERE id=?');$st->execute([$id]);$order=$st->fetch();
if(!$order){http_response_code(404);exit('Order not found.');}
$st=$pdo->prepare('SELECT product_title,price,quantity,product_id FROM order_items WHERE order_id=?');$st->execute([$id]);$items=$st->fetchAll();
function money_kes($n){return 'KSh '.number_format((float)$n,2);}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Order <?=e($order['order_code'])?> · EarnsStore</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-slate-100 text-slate-900"><header class="bg-slate-950 text-white p-4"><div class="max-w-5xl mx-auto flex justify-between"><b>EARN <span class="text-orange-400">ORDER DETAILS</span></b><a href="admin.php" class="underline">← Back to dashboard</a></div></header><main class="max-w-5xl mx-auto p-4 space-y-4"><section class="bg-white rounded-xl p-6 shadow-sm"><div class="flex flex-wrap justify-between gap-3"><div><p class="text-slate-500 text-sm">Order reference</p><h1 class="text-3xl font-black"><?=e($order['order_code'])?></h1><p class="text-sm text-slate-500 mt-1">Placed <?=e($order['created_at'])?></p></div><span class="bg-orange-100 text-orange-800 rounded-full px-4 py-2 h-fit font-bold"><?=e($order['status'])?></span></div></section><div class="grid md:grid-cols-2 gap-4"><section class="bg-white rounded-xl p-6 shadow-sm"><h2 class="font-black text-xl mb-3">Customer & delivery</h2><p><b><?=e($order['customer_name'])?></b></p><p><?=e($order['email'])?></p><p><?=e($order['phone'])?></p><p class="mt-3 whitespace-pre-line"><?=e($order['address'])?></p><p class="mt-3 text-sm text-slate-500">Payment: <?=e($order['payment_method'])?></p></section><section class="bg-white rounded-xl p-6 shadow-sm"><h2 class="font-black text-xl mb-3">Order summary</h2><div class="flex justify-between py-2"><span>Subtotal</span><b><?=money_kes($order['subtotal'])?></b></div><div class="flex justify-between py-2"><span>Delivery</span><b><?=money_kes($order['delivery_fee'])?></b></div><div class="flex justify-between border-t mt-2 pt-3 text-xl"><span>Total</span><b><?=money_kes($order['total'])?></b></div></section></div><section class="bg-white rounded-xl p-6 shadow-sm"><h2 class="font-black text-xl mb-3">Items ordered</h2><div class="overflow-x-auto"><table class="w-full text-left"><thead><tr class="border-b"><th class="py-2">Product</th><th>Unit price</th><th>Quantity</th><th>Total</th></tr></thead><tbody><?php foreach($items as $it):?><tr class="border-b"><td class="py-3"><?=e($it['product_title'])?></td><td><?=money_kes($it['price'])?></td><td><?=e($it['quantity'])?></td><td><?=money_kes($it['price']*$it['quantity'])?></td></tr><?php endforeach;?></tbody></table></div></section></main></body></html>